// ---------------------------------------------------------------------------
// SEXPTYPE — unsigned int tag identifying the content type of a SEXPREC node.
//
// Source: Rinternals.h lines 109-144 (non-enum_SEXPTYPE branch, active by
// default when the compiler does not define enum_SEXPTYPE).
//
// The original header comment notes that slots 11 and 12 were used for
// factors in the 1990s and are now intentionally unassigned.
// ---------------------------------------------------------------------------
#ifndef FAKE_SEXPTYPE_DEFINED
#define FAKE_SEXPTYPE_DEFINED

typedef unsigned int SEXPTYPE;

#define NILSXP       0    /* nil = NULL */
#define SYMSXP       1    /* symbols */
#define LISTSXP      2    /* lists of dotted pairs */
#define CLOSXP       3    /* closures */
#define ENVSXP       4    /* environments */
#define PROMSXP      5    /* promises: [un]evaluated closure arguments */
#define LANGSXP      6    /* language constructs (special lists) */
#define SPECIALSXP   7    /* special forms */
#define BUILTINSXP   8    /* builtin non-special forms */
#define CHARSXP      9    /* "scalar" string type (internal only) */
#define LGLSXP      10    /* logical vectors */
/* 11 and 12 were used for factors in the 1990s — intentionally unassigned */
#define INTSXP      13    /* integer vectors */
#define REALSXP     14    /* real (double) variables */
#define CPLXSXP     15    /* complex variables */
#define STRSXP      16    /* string vectors */
#define DOTSXP      17    /* dot-dot-dot object */
#define ANYSXP      18    /* make "any" args work */
#define VECSXP      19    /* generic vectors */
#define EXPRSXP     20    /* expressions vectors */
#define BCODESXP    21    /* byte code */
#define EXTPTRSXP   22    /* external pointer */
#define WEAKREFSXP  23    /* weak reference */
#define RAWSXP      24    /* raw bytes */
#define OBJSXP      25    /* object, non-vector (S4) */
#define S4SXP       25    /* same as OBJSXP, retained for back compatibility */
#define NEWSXP      30    /* fresh node created in new page */
#define FREESXP     31    /* node released by GC */
#define FUNSXP      99    /* Closure or Builtin or Special */

#endif // FAKE_SEXPTYPE_DEFINED

// ---------------------------------------------------------------------------
// SEXPREC and SEXP — minimal fake matching the observable C API contract.
//
// Fields derived from the usage patterns in the rpart source:
//   type   — stores the SEXPTYPE tag; set by allocVector/allocMatrix.
//   length — total element count; returned by LENGTH().
//   nrow   — row count for matrices; returned by nrows() / Rf_nrows().
//   ncol   — column count for matrices; returned by ncols() / Rf_ncols().
//   data   — void * to the heap-allocated element buffer; cast by INTEGER(),
//            REAL(), LOGICAL(), RAW() to their respective pointer types.
//
// Both the SEXPREC node and its data buffer are heap-allocated via malloc().
// They are NOT arena-managed: returned SEXPs must outlive the function frame
// (they are the .Call return values consumed by Python).  See Arena/Memory
// Notes in the guide (Section 4) for the distinction between SEXP allocations
// and R_alloc / ALLOC scratch allocations.
// ---------------------------------------------------------------------------
#ifndef FAKE_SEXPREC_DEFINED
#define FAKE_SEXPREC_DEFINED

struct SEXPREC {
    SEXPTYPE  type;    /* one of the SEXPTYPE tags above */
    int       length;  /* total element count (used by LENGTH()) */
    int       nrow;    /* row count for matrices (used by nrows()) */
    int       ncol;    /* column count for matrices (used by ncols()) */
    void     *data;    /* pointer to the element buffer (heap-allocated) */
};

typedef SEXPREC *SEXP;

#endif // FAKE_SEXPREC_DEFINED

// ---------------------------------------------------------------------------
// sexptype_element_size — returns sizeof(element) for a given SEXPTYPE.
// Used by allocVector and allocMatrix to size the data buffer correctly.
// INTSXP and LGLSXP both use int; REALSXP uses double; etc.
// ---------------------------------------------------------------------------
#ifndef FAKE_SEXPTYPE_ELEMENT_SIZE_DEFINED
#define FAKE_SEXPTYPE_ELEMENT_SIZE_DEFINED

inline size_t sexptype_element_size(SEXPTYPE type) {
    switch (type) {
        case INTSXP:
        case LGLSXP:    return sizeof(int);
        case REALSXP:   return sizeof(double);
        case CPLXSXP:   return 2 * sizeof(double);
        case RAWSXP:    return sizeof(unsigned char);
        case STRSXP:
        case VECSXP:
        case EXPRSXP:   return sizeof(SEXP);
        default:        return sizeof(int);
    }
}

#endif // FAKE_SEXPTYPE_ELEMENT_SIZE_DEFINED

// ---------------------------------------------------------------------------
// Core fake implementation — allocVector
//
// Pattern: 1-D integer vector allocation
// Locations: pred_rpart.c:139, rpart.c:194, rpartexp2.c:47
//   SEXP where = PROTECT(allocVector(INTSXP, n));
//   SEXP which3 = PROTECT(allocVector(INTSXP, n));
//   SEXP keep  = PROTECT(allocVector(INTSXP, n));
//
// When type == INTSXP, data holds int[length], zero-initialised.
// INTEGER(sexp) returns int * into this buffer.
//
// The SEXPREC node and its data buffer are both heap-allocated via malloc().
// On failure, RError is thrown (Invariant 1: C++ exception-based errors).
// ---------------------------------------------------------------------------
#ifndef FAKE_ALLOCVECTOR_DEFINED
#define FAKE_ALLOCVECTOR_DEFINED

inline SEXP allocVector(SEXPTYPE type, int length) {
    SEXPREC *s = (SEXPREC *) malloc(sizeof(SEXPREC));
    if (!s) throw RError("allocVector: out of memory allocating SEXPREC node");
    s->type   = type;
    s->length = length;
    s->nrow   = length;
    s->ncol   = 1;
    size_t bytes = (size_t) length * sexptype_element_size(type);
    s->data = malloc(bytes);
    if (!s->data) {
        free(s);
        throw RError("allocVector: out of memory allocating data buffer");
    }
    memset(s->data, 0, bytes);
    return s;
}

/* Rf_allocVector — canonical name in Rinternals.h; alias to allocVector. */
inline SEXP Rf_allocVector(SEXPTYPE type, int length) {
    return allocVector(type, length);
}

#endif // FAKE_ALLOCVECTOR_DEFINED

// ---------------------------------------------------------------------------
// Core fake implementation — allocMatrix
//
// Pattern: 2-D integer matrix allocation
// Locations: rpart.c:278, rpart.c:285, rpart.c:293
//   inode3  = PROTECT(allocMatrix(INTSXP, nodecount, 6));
//   isplit3 = PROTECT(allocMatrix(INTSXP, splitcount, 3));
//   csplit3 = PROTECT(allocMatrix(INTSXP, catcount, maxcat));
//
// Stores a flat column-major int[nrow * ncol] buffer.
// Column j starts at INTEGER(s) + j * nrow.
// The rpart source advances iptr by nrow per column:
//   for (i = 0; i < 6; i++) { iinode[i] = iptr; iptr += nodecount; }
// This is correct for column-major layout over a flat buffer.
// ---------------------------------------------------------------------------
#ifndef FAKE_ALLOCMATRIX_DEFINED
#define FAKE_ALLOCMATRIX_DEFINED

inline SEXP allocMatrix(SEXPTYPE type, int nrow, int ncol) {
    /* Delegate to allocVector for the flat buffer, then fix up dimensions. */
    SEXP s = allocVector(type, nrow * ncol);
    s->nrow = nrow;
    s->ncol = ncol;
    return s;
}

/* Rf_allocMatrix — canonical name in Rinternals.h; alias to allocMatrix. */
inline SEXP Rf_allocMatrix(SEXPTYPE type, int nrow, int ncol) {
    return allocMatrix(type, nrow, ncol);
}

#endif // FAKE_ALLOCMATRIX_DEFINED

