// ---------------------------------------------------------------------------
// PROTECT / UNPROTECT — no-ops in the fake runtime (no garbage collector).
//
// PROTECT(expr) must return the SEXP produced by expr, identical to the real
// R API.  The inline Rf_protect(SEXP) wrapper achieves this: the compiler
// sees a function call whose return value is the same SEXP passed in.
//
// Usage in every CSV row:
//   SEXP where = PROTECT(allocVector(INTSXP, n));   // pred_rpart.c:139
//   which3 = PROTECT(allocVector(INTSXP, n));        // rpart.c:194
//   inode3 = PROTECT(allocMatrix(INTSXP, ...));      // rpart.c:278
//   ...
//   UNPROTECT(1);                                    // after each .Call entry
// ---------------------------------------------------------------------------
#ifndef FAKE_PROTECT_DEFINED
#define FAKE_PROTECT_DEFINED

inline SEXP Rf_protect(SEXP s)           { return s; }
inline void Rf_unprotect(int /*n*/)      {}
inline void Rf_unprotect_ptr(SEXP /*s*/) {}

#endif // FAKE_PROTECT_DEFINED

// ---------------------------------------------------------------------------
// free_sexp — releases the heap memory for a SEXP and its data buffer.
// Python-side wrappers must call this after extracting element data into
// numpy arrays (or equivalent), to avoid leaking the malloc'd SEXPREC node.
// This function has no counterpart in the real R API (GC handles cleanup).
// ---------------------------------------------------------------------------
#ifndef FAKE_FREE_SEXP_DEFINED
#define FAKE_FREE_SEXP_DEFINED

inline void free_sexp(SEXP s) {
    if (s) {
        free(s->data);
        free(s);
    }
}

#endif // FAKE_FREE_SEXP_DEFINED

