// ---------------------------------------------------------------------------
// --- ArenaFrame usage (Category A with arena-adjacent context) ---
//
// INTSXP itself is a compile-time constant and does not trigger arena use.
// However, the functions that call allocVector(INTSXP,...) and
// allocMatrix(INTSXP,...) (namely rpart() in rpart.c and rpartexp2() in
// rpartexp2.c) also call ALLOC / R_alloc for scratch arrays in the same
// function body.  Those scratch allocations ARE arena-managed via fake_arena.h.
//
// Once fake_arena.h is available, declare `ArenaFrame _frame;` as the FIRST
// statement of every .Call-entry wrapper function that invokes arena-backed
// functions.  Example:
//
//   extern "C" SEXP rpart_entry(SEXP ncat, SEXP method, ...) {
//       ArenaFrame _frame;    // <-- frees all R_alloc/ALLOC scratch on exit
//       try {
//           return rpart(ncat, method, ...);
//       } catch (const RError &e) {
//           set_python_error(e.what());
//           return nullptr;
//       }
//   }
//
//   extern "C" SEXP pred_rpart_entry(SEXP dimx, ...) {
//       ArenaFrame _frame;    // needed only if pred_rpart calls R_alloc
//       try {
//           return pred_rpart(dimx, ...);
//       } catch (const RError &e) {
//           set_python_error(e.what());
//           return nullptr;
//       }
//   }
//
// The SEXP return values (where, which3, inode3, isplit3, csplit3, keep)
// are heap-allocated and survive the ArenaFrame destruction.  They must
// be passed back to Python, which calls free_sexp() after copying data.
// ---------------------------------------------------------------------------

#endif // FAKE_INTSXP_H
